questionvariables.text:
/* Design: construct-an-example pattern: the response tree checks the properties, so any list that works is accepted. Source: original. */
C: [[4,3,6],[3,1,4],[4,3,4],[2,2,4],[4,1,4],[3,2,4],[4,2,6],[4,1,6],[2,1,4],[2,1,6]];
ix: 1+rand(10);
nev: C[ix][1]; k: C[ix][2]; m: C[ix][3];
a: min(nev,k);
/* m is 4 or 6: 8 is even and greater than m, 2 even and not, 9 odd and greater, 1 odd and not */
ta: sort(append(makelist(8,j,1,a), makelist(2,j,1,nev-a), makelist(9,j,1,k-a), makelist(1,j,1,6-nev-k+a)));
validate_faces(ex) := if listp(ex) and length(ex)=6 and every(lambda([v], integerp(ev(v,simp)) and ev(v,simp)>=1 and ev(v,simp)<=9), ex) then "" else "Type exactly six whole numbers from 1 to 9 in square brackets, separated by commas.";
/* test lists: one 8 replaced by m (counted m as greater); one 1 replaced by 9 (too many greater); one 1 replaced by 2 (too many even) */
tm: sort(append([m], rest(sublist(ta, lambda([v], v=8))), sublist(ta, lambda([v], v#8))));
t9: sort(append([9], rest(sublist(ta, lambda([v], v=1))), sublist(ta, lambda([v], v#1))));
t2: sort(append([2], rest(sublist(ta, lambda([v], v=1))), sublist(ta, lambda([v], v#1))));

feedbackvariables.text:
ne: length(sublist(ans1, evenp));
ng: length(sublist(ans1, lambda([v], v>m)));
nge: length(sublist(ans1, lambda([v], v>=m)));
